function safeStorage(method, key, value) { try { if (method === "get") return localStorage.getItem(key); localStorage.setItem(key, value); } catch { return null; } return null; }
function text(path) { return path.split(".").reduce((value, part) => value && value[part], COPY[state.language]) || path; }
function esc(value) { return String(value || "").replace(/[&<>'"]/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;" })[char]); }
